<section class="page-heading"><span class="eyebrow">Administration</span><h1>Catalogue dashboard</h1><p>Review scheme quality, publication status, and recent administrative changes.</p></section><div class="stats-grid"><?php foreach(['total'=>'Total schemes','active'=>'Active','inactive'=>'Inactive or archived','review'=>'Needs review','categories'=>'Categories'] as $k=>$label): ?><div class="stat-card"><span><?=e($label)?></span><strong><?=e($stats[$k])?></strong></div><?php endforeach; ?></div><div class="admin-actions"><a class="button" href="<?=e(url('admin_scheme'))?>">Create scheme</a><a class="button button-outline" href="<?=e(url('admin_schemes'))?>">Manage schemes</a><a class="button button-outline" href="<?=e(url('admin_review'))?>">Verification queue</a><a class="button button-outline" href="<?=e(url('admin_categories'))?>">Manage categories</a><a class="button button-outline" href="<?=e(url('admin_audit'))?>">Audit log</a></div><section class="panel"><h2>Recent administration actions</h2><?php if(!$recent): ?><p>No changes recorded yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Action</th><th>Record</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?=e(str_replace('_',' ',$r['action']))?></td><td><?=e($r['entity_type'])?> #<?=e($r['entity_id'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
